class Solution {
public:
    int maximumNumberOfOnes(int width, int height, int sideLength, int maxOnes) {
        vector<int> counts;
        counts.reserve(sideLength * sideLength);
        for (int r = 0; r < sideLength; ++r) {
            for (int c = 0; c < sideLength; ++c) {
                int r_count = (height - 1 - r) / sideLength + 1;
                int c_count = (width - 1 - c) / sideLength + 1;
                counts.push_back(r_count * c_count);
            }
        }
        sort(counts.rbegin(), counts.rend());
        int total = 0;
        for (int i = 0; i < maxOnes; ++i) total += counts[i];
        return total;
    }
};

import java.util.*;

class Solution {
    public int maximumNumberOfOnes(int width, int height, int sideLength, int maxOnes) {
        int[] counts = new int[sideLength * sideLength];
        int idx = 0;
        for (int r = 0; r < sideLength; r++) {
            for (int c = 0; c < sideLength; c++) {
                int rCount = (height - 1 - r) / sideLength + 1;
                int cCount = (width - 1 - c) / sideLength + 1;
                counts[idx++] = rCount * cCount;
            }
        }
        Arrays.sort(counts);
        int total = 0;
        int n = counts.length;
        for (int i = 0; i < maxOnes; i++) {
            total += counts[n - 1 - i];
        }
        return total;
    }
}

var maximumNumberOfOnes = function(width, height, sideLength, maxOnes) {
    const counts = [];
    for (let r = 0; r < sideLength; r++) {
        for (let c = 0; c < sideLength; c++) {
            const rCount = Math.floor((height - 1 - r) / sideLength) + 1;
            const cCount = Math.floor((width - 1 - c) / sideLength) + 1;
            counts.push(rCount * cCount);
        }
    }
    counts.sort((a, b) => b - a);
    let total = 0;
    for (let i = 0; i < maxOnes; i++) total += counts[i];
    return total;
};
